_PLANS = _DATA["plans"]
_ROUTES = {tuple(row["shops"]): int(row["plan"]) for row in _DATA["routes"]}
_FIRST = dict(_DATA["first"])
_STATE = {}
WEED_BLOCKED = {"PLANT", "BUILD_COOP", "BUILD_PASTURE"}


def _get(obj, key, default=None):
    if obj is None:
        return default
    if isinstance(obj, dict):
        return obj.get(key, default)
    try:
        return obj[key]
    except Exception:
        return getattr(obj, key, default)


def _repair_weeds(action, observation, queues):
    farm = observation["farms"][observation["player"]]
    tiles = farm["tiles"]
    positions = [tuple(farm["farmer"])] + [tuple(p) for p in (farm.get("hands") or [])]
    workers = [list(action.get("farmer") or ["PASS"])]
    workers.extend(list(h) if h else ["PASS"] for h in (action.get("hands") or []))
    while len(workers) < len(positions):
        workers.append(["PASS"])
    for index in range(min(len(workers), len(positions))):
        queue = queues.setdefault(index, deque())
        queue.append(list(workers[index]))
        x, y = positions[index]
        tile = None
        if 0 <= y < len(tiles) and 0 <= x < len(tiles[y]):
            tile = tiles[y][x]
        blocked = (
            queue[0]
            and queue[0][0] in WEED_BLOCKED
            and isinstance(tile, dict)
            and tile.get("kind") == "WEED"
        )
        workers[index] = ["DIG"] if blocked else queue.popleft()
    action["farmer"] = workers[0]
    action["hands"] = workers[1 : len(positions)]
    return action


def _trim_sales(action, observation):
    private = _get(observation, "private") or {}
    shed = dict(_get(private, "shed") or {})
    market = []
    for order in action.get("market") or []:
        if not order:
            continue
        if order[0] == "SELL" and len(order) >= 3:
            item = order[1]
            have = int(shed.get(item) or 0)
            qty = min(max(0, int(order[2])), have)
            if qty <= 0:
                continue
            shed[item] = have - qty
            market.append(["SELL", item, qty])
        else:
            market.append(list(order) if isinstance(order, list) else order)
    action["market"] = market[:10]
    return action


def _pad(action, n_hands):
    hands = [list(h) if h else ["PASS"] for h in (action.get("hands") or [])]
    if len(hands) < n_hands:
        hands.extend([["PASS"] for _ in range(n_hands - len(hands))])
    else:
        hands = hands[:n_hands]
    action["hands"] = hands
    farmer = list(action.get("farmer") or ["PASS"])
    action["farmer"] = farmer
    return action


def agent(observation, configuration=None):
    step = int(_get(observation, "step", 0) or 0)
    player = int(_get(observation, "player", 0) or 0)
    farm = observation["farms"][player]
    n_hands = len(farm.get("hands") or [])
    rec = _STATE.get(player)
    if rec is None or step <= rec.get("last", -1):
        rec = {"last": -1, "plan": 0, "queues": {}}
        _STATE[player] = rec
    rec["last"] = step
    shops = tuple(_get(_get(observation, "town", {}) or {}, "unlocked_shops", []) or [])
    if step >= 144 and len(shops) >= 2:
        rec["plan"] = _ROUTES.get(shops[:2], rec.get("plan", 0))
    plan = int(rec.get("plan") or 0)
    if plan < 0 or plan >= len(_PLANS):
        plan = 0
    tape = _PLANS[plan]
    if step < 0 or step >= len(tape):
        return {"farmer": ["PASS"], "hands": [["PASS"] for _ in range(n_hands)], "market": []}
    farmer, hands, market = tape[step]
    action = {
        "farmer": list(farmer) if farmer else ["PASS"],
        "hands": [list(h) if h else ["PASS"] for h in (hands or [])],
        "market": [list(o) if isinstance(o, list) else o for o in (market or [])],
    }
    try:
        action = _repair_weeds(action, observation, rec["queues"])
        action = _trim_sales(action, observation)
    except Exception:
        pass
    return _pad(action, n_hands)


